# Version script for libfeme_vulkan.so (see "Process Coexistence and Symbol
# Visibility" in feme/docs/FeMeVulkanDesign.md): exports only the
# loader-facing entrypoints. Every other symbol -- LLVM, MLIR, and FeMe's own
# -- must stay hidden so this ICD can share a process with another
# LLVM-based Vulkan driver without colliding global state.
FEME_VULKAN_1.0 {
  global:
    vk_icdNegotiateLoaderICDInterfaceVersion;
    vk_icdGetInstanceProcAddr;
    vk_icdGetPhysicalDeviceProcAddr;
    vkGetInstanceProcAddr;
  local:
    *;
};
